async function getUser(id: string): Promise<User> {
  const key = `user:${id}`;
  const cached = await redis.get(key);
  if (cached) return JSON.parse(cached);          // hit

  const user = await db.users.findById(id);        // miss
  await redis.set(key, JSON.stringify(user), "EX", 300); // TTL 5 min
  return user;
}

async function updateUser(id: string, patch: Partial<User>) {
  await db.users.update(id, patch);
  await redis.del(`user:${id}`);                 // invalidate, don't update
}

// Minimal consistent hash ring with virtual nodes
import { createHash } from "node:crypto";
const h = (s: string) => parseInt(createHash("md5").update(s).digest("hex").slice(0, 8), 16);

class Ring {
  private points: { hash: number; node: string }[] = [];
  constructor(nodes: string[], private vnodes = 100) { nodes.forEach((n) => this.add(n)); }
  add(node: string) {
    for (let i = 0; i < this.vnodes; i++) this.points.push({ hash: h(`${node}#${i}`), node });
    this.points.sort((a, b) => a.hash - b.hash);
  }
  get(key: string): string {
    const k = h(key);
    let lo = 0, hi = this.points.length;          // first point with hash >= k
    while (lo < hi) { const m = (lo + hi) >> 1; this.points[m].hash < k ? (lo = m + 1) : (hi = m); }
    return this.points[lo % this.points.length].node; // wrap around the ring
  }
}

// G-Counter CRDT: each replica only increments its own slot; merge = element-wise max
type GCounter = Record<string, number>;

const increment = (c: GCounter, replica: string): GCounter =>
  ({ ...c, [replica]: (c[replica] ?? 0) + 1 });

const merge = (a: GCounter, b: GCounter): GCounter => {
  const out: GCounter = { ...a };
  for (const [r, n] of Object.entries(b)) out[r] = Math.max(out[r] ?? 0, n);
  return out;
};

const value = (c: GCounter) => Object.values(c).reduce((s, n) => s + n, 0);

// Idempotent payment endpoint (simplified)
app.post("/payments", async (req, res) => {
  const key = req.header("Idempotency-Key");
  if (!key) return res.status(400).send("Idempotency-Key required");

  const result = await db.transaction(async (tx) => {
    // unique constraint on idempotency_keys.key makes concurrent duplicates fail fast
    const existing = await tx.idempotencyKeys.find(key);
    if (existing) return existing.response;

    const charge = await tx.payments.create({ amount: req.body.amount, userId: req.user.id });
    const response = { paymentId: charge.id, status: "succeeded" };
    await tx.idempotencyKeys.insert({ key, response, userId: req.user.id });
    return response;
  });
  res.json(result);
});

