const ALPHABET = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";

function toBase62(n: bigint): string {
  if (n === 0n) return "0";
  let s = "";
  while (n > 0n) {
    s = ALPHABET[Number(n % 62n)] + s;
    n /= 62n;
  }
  return s;
}

toBase62(125n);            // "21"
toBase62(3_521_614_606_207n); // "ZZZZZZZ" = 62^7 - 1

function useAutocomplete(query: string) {
  const [results, setResults] = useState<string[]>([]);
  const cache = useRef(new Map<string, string[]>());

  useEffect(() => {
    const q = query.trim().toLowerCase();
    if (q.length < 2) return setResults([]);
    if (cache.current.has(q)) return setResults(cache.current.get(q)!);

    const ctrl = new AbortController();
    const timer = setTimeout(async () => {
      try {
        const res = await fetch(`/api/suggest?q=${encodeURIComponent(q)}`, { signal: ctrl.signal });
        const data: string[] = await res.json();
        cache.current.set(q, data);
        setResults(data);
      } catch (e) {
        if ((e as Error).name !== "AbortError") console.error(e);
      }
    }, 200);                                   // debounce

    return () => { clearTimeout(timer); ctrl.abort(); }; // cancel stale work
  }, [query]);

  return results;
}
